// Registers Amazon's Vega-patched Shaka Player as the player's HLS/DASH engine.
// The compiled player and Amazon's polyfills live in ./vendor, generated by
// vega-tv/scripts/build-shaka.sh (git-ignored: Amazon Program Materials).
//
// Configuration mirrors Amazon's reference wrapper (shaka-rel ShakaPlayer.ts):
// fetch-based networking, no in-band caption parsing, small live buffers.
import type {VideoPlayer} from '@amazon-devices/react-native-w3cmedia';
import {AdaptiveOptions, AdaptiveSession, registerAdaptivePlayer} from '../adaptive';
// @ts-ignore: generated vendor files have no type information.
import Document from './vendor/polyfills/DocumentPolyfill';
// @ts-ignore
import Element from './vendor/polyfills/ElementPolyfill';
// @ts-ignore
import TextDecoderPolyfill from './vendor/polyfills/TextDecoderPolyfill';
// @ts-ignore
import W3CMediaPolyfill from './vendor/polyfills/W3CMediaPolyfill';
// @ts-ignore
import MiscPolyfill from './vendor/polyfills/MiscPolyfill';

let shaka: any = null;
let installed = false;

function install(log: (line: string) => void) {
  if (installed) {
    return;
  }
  Document.install();
  Element.install();
  TextDecoderPolyfill.install();
  W3CMediaPolyfill.install();
  MiscPolyfill.install();
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const mod = require('./vendor/shaka-player.compiled.js');
  shaka = (mod && (mod.default || mod)) || (globalThis as any).shaka;
  shaka.polyfill.installAll();
  const {NetworkingEngine, HttpFetchPlugin} = shaka.net;
  NetworkingEngine.unregisterScheme('http');
  NetworkingEngine.unregisterScheme('https');
  NetworkingEngine.registerScheme('http', HttpFetchPlugin.parse, NetworkingEngine.PluginPriority.APPLICATION, true);
  NetworkingEngine.registerScheme('https', HttpFetchPlugin.parse, NetworkingEngine.PluginPriority.APPLICATION, true);
  try {
    shaka.media.ClosedCaptionParser.unregisterParser('video/mp4');
    shaka.media.ClosedCaptionParser.unregisterParser('video/mp2t');
  } catch {
    // Older builds have no caption parser registry.
  }
  // The compiled (release) Shaka build strips its debug logger, so `shaka.log` may be absent.
  if (shaka.log && typeof shaka.log.setLevel === 'function' && shaka.log.Level) {
    shaka.log.setLevel(shaka.log.Level.WARNING);
  }
  installed = true;
  log(`shaka ${shaka.Player.version} ready`);
}

export function registerShaka(log: (line: string) => void = () => undefined): void {
  registerAdaptivePlayer((media: VideoPlayer, url: string, options: AdaptiveOptions): AdaptiveSession => {
    install(log);
    const player = new shaka.Player(media);
    player.configure({
      streaming: {
        lowLatencyMode: false,
        inaccurateManifestTolerance: 0,
        rebufferingGoal: 0.01,
        bufferingGoal: options.live ? 12 : 20,
        bufferBehind: options.live ? 8 : 15,
        retryParameters: {maxAttempts: 4, baseDelay: 500, backoffFactor: 1.5, timeout: 15000},
        infiniteLiveStreamDuration: true,
        // Live TV must never give up on a short hiccup; Shaka re-requests the playlist.
        failureCallback: (error: any) => log(`shaka stream failure ${error?.code}`),
      },
      manifest: {
        dash: {disableXlinkProcessing: true},
        hls: {useSafariBehaviorForLive: false, disableClosedCaptionsDetection: true},
        retryParameters: {maxAttempts: 4, baseDelay: 500, backoffFactor: 1.5, timeout: 15000},
      },
      preferredAudioLanguage: 'en',
      abr: {enabled: true, restrictions: {maxWidth: 3840, maxHeight: 2160}},
    });
    player.addEventListener('error', (event: any) => log(`shaka error ${event?.detail?.code} ${event?.detail?.message || ''}`));
    let unloaded = false;
    player
      .load(url, options.live ? null : options.startAt || 0)
      .then(() => {
        log(`shaka loaded ${options.live ? 'live' : 'vod'} stream`);
        if (options.autoplay && !unloaded) {
          const r: any = media.play();
          r?.catch?.(() => undefined);
        }
      })
      .catch((error: any) => {
        log(`shaka load failed ${error?.code} ${error?.message || ''}`);
        // Surface as a media error so the screen's failover logic runs.
        (media as any).dispatchEvent?.({type: 'error'});
      });
    return {
      unload: async () => {
        unloaded = true;
        try {
          await player.unload();
        } catch {
          // Already unloaded.
        }
        try {
          await player.destroy();
        } catch {
          // Already destroyed.
        }
      },
    };
  });
}
